-- =====================================================================
-- SE-EWRS : seed.sql   (GENERATED FILE -- do not edit by hand)
-- Regenerate with:
--   cd backend && python -m app.db.seed --emit-sql ../database/seed.sql
--
-- Purpose : realistic fictional demo data. Every name, roll number and
--           email in this file is invented; no real student record or
--           personal data is present.
--
-- Load order:   schema.sql -> views.sql -> procedures.sql -> triggers.sql
--               -> seed.sql
--   mysql -u <user> -p se_ewrs < database/seed.sql
--
-- Dates are written as CURDATE() arithmetic rather than fixed dates, so
-- the demo stays current whenever it is loaded.
--
-- Demo sign-in: every account below uses the password Demo@12345
-- (one shared Argon2id digest). Change it before any real deployment.
-- =====================================================================

USE se_ewrs;

-- Clear only the demo-owned tables. system_settings is left untouched so
-- a tuned risk model survives a reseed.
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM interventions;
DELETE FROM alert_status_history;
DELETE FROM risk_alerts;
DELETE FROM risk_assessments;
DELETE FROM assessment_results;
DELETE FROM assessments;
DELETE FROM lms_activity_logs;
DELETE FROM attendance_records;
DELETE FROM enrollments;
DELETE FROM course_instructors;
DELETE FROM courses;
DELETE FROM students;
DELETE FROM audit_logs;
DELETE FROM users;
DELETE FROM departments;
SET FOREIGN_KEY_CHECKS = 1;

-- Disable the audit triggers' noise during a bulk load by simply
-- accepting it: the audit rows written here are part of the demo.

-- 4 row(s) into departments

-- 11 row(s) into users

-- 36 row(s) into students

-- 6 row(s) into courses

-- 9 row(s) into course_instructors

-- 80 row(s) into enrollments

-- 1694 row(s) into attendance_records

-- 5414 row(s) into lms_activity_logs

-- 30 row(s) into assessments

-- percentage is deliberately NOT supplied here: the
-- trg_ar_before_insert trigger derives it from max_marks, which is
-- what proves the trigger is doing its job after a bulk load.

-- 380 row(s) into assessment_results


-- =====================================================================
-- Generate risk scores and early-warning alerts using the stored
-- procedure, rather than hardcoding them. This is also the quickest way
-- to confirm that procedures.sql loaded correctly.
-- =====================================================================
CALL sp_recalculate_all_risk(NULL, 1);

-- 12 row(s) into interventions


-- =====================================================================
-- Move a few alerts past NEW so the demo queue shows real working state.
-- sp_update_alert_status enforces the legal transitions and writes the
-- matching alert_status_history rows.
-- =====================================================================
CALL sp_update_alert_status(
    (SELECT MIN(alert_id) FROM risk_alerts WHERE status = 'NEW'),
    'ACKNOWLEDGED', 8, 'Reviewed in the weekly advising meeting.');
CALL sp_update_alert_status(
    (SELECT MIN(alert_id) FROM risk_alerts WHERE status = 'NEW'),
    'IN_PROGRESS', 8, 'Counselling session booked with the student.');
CALL sp_update_alert_status(
    (SELECT MIN(alert_id) FROM risk_alerts WHERE status = 'NEW'),
    'ACKNOWLEDGED', 9, 'Contacted the student by email; awaiting a reply.');
CALL sp_update_alert_status(
    (SELECT MIN(alert_id) FROM risk_alerts WHERE status = 'NEW'),
    'IN_PROGRESS', 9, 'Tutoring referral raised.');

UPDATE risk_alerts SET assigned_to = 8
 WHERE status IN ('ACKNOWLEDGED', 'IN_PROGRESS') AND assigned_to IS NULL;

-- =====================================================================
-- Load summary
-- =====================================================================
SELECT 'seed.sql applied successfully' AS status;
SELECT
    (SELECT COUNT(*) FROM students)          AS students,
    (SELECT COUNT(*) FROM courses)           AS courses,
    (SELECT COUNT(*) FROM enrollments)       AS enrollments,
    (SELECT COUNT(*) FROM attendance_records) AS attendance_rows,
    (SELECT COUNT(*) FROM lms_activity_logs) AS activity_rows,
    (SELECT COUNT(*) FROM assessment_results) AS result_rows,
    (SELECT COUNT(*) FROM risk_assessments)  AS risk_rows,
    (SELECT COUNT(*) FROM risk_alerts)       AS alerts,
    (SELECT COUNT(*) FROM interventions)     AS interventions;

SELECT risk_category, COUNT(*) AS enrollments
  FROM student_risk_summary
 GROUP BY risk_category
 ORDER BY FIELD(risk_category, 'HIGH', 'MEDIUM', 'LOW', 'INSUFFICIENT_DATA');
